20	/**
21	 * @implements Rule<\PhpParser\Node\Stmt\ClassMethod>
22	 */
23	final class TestNamingConventionRule implements Rule
24	{
25	    /** @readonly */
26	    private RulePathNormalizer $pathNormalizer;
27	
28	    /** @readonly */
29	    private SourceFileRuleMatcher $sourceFileMatcher;
30	
31	    /** @readonly */
32	    private PublicMethodTestCoverageValidator $publicMethodValidator;
33	
34	    /** @readonly */
35	    private TestMethodNameValidator $testMethodNameValidator;
36	
37	    /** @readonly */
38	    private ProviderNameValidator $providerNameValidator;
39	
40	    /**
41	     * @param TestClassScope $testClassScope test class scope detector
42	     * @param string $srcMarker path marker identifying source directories
43	     * @param string $unitTestMarker path marker identifying unit test directories
44	     */
45	    public function __construct(
46	        /** @readonly */
47	        private TestClassScope $testClassScope,
48	        /** @readonly */
49	        private string $srcMarker = '/src/',
50	        string $unitTestMarker = '/tests/Unit/',
51	        ?RulePathNormalizer $pathNormalizer = null,
52	        ?SourceFileRuleMatcher $sourceFileMatcher = null,
53	        ?PublicMethodTestCoverageValidator $publicMethodValidator = null,
54	        ?TestMethodNameValidator $testMethodNameValidator = null,
55	        ?ProviderNameValidator $providerNameValidator = null,
56	    ) {
57	        $this->pathNormalizer = $pathNormalizer ?? new RulePathNormalizer();
58	        $this->sourceFileMatcher = $sourceFileMatcher ?? new SourceFileRuleMatcher();
59	        $this->publicMethodValidator = $publicMethodValidator ?? new PublicMethodTestCoverageValidator(
60	            new SourceUnitTestFileResolver($srcMarker, $unitTestMarker),
61	        );
62	        $this->testMethodNameValidator = $testMethodNameValidator ?? new TestMethodNameValidator();
63	        $this->providerNameValidator = $providerNameValidator ?? new ProviderNameValidator();
64	    }
65	
66	    /**
67	     * @return class-string<ClassMethod>
68	     */
69	    public function getNodeType(): string
70	    {
71	        return ClassMethod::class;
72	    }
73	
74	    /**
75	     * @param ClassMethod $node
76	     * @return list<IdentifierRuleError>
77	     */
78	    public function processNode(Node $node, Scope $scope): array
79	    {
80	        if ($this->testClassScope->isPropertyTestClass($scope)) {
81	            return [];
82	        }
83	
84	        $file = $this->pathNormalizer->normalize($scope->getFile());
85	
86	        if ($this->sourceFileMatcher->isSourceFile($file, $this->srcMarker)) {
87	            return $this->publicMethodValidator->errors($node, $file);
88	        }
89	
90	        if ($this->testClassScope->isRestrictedTestClass($scope)) {
91	            $methodName = $node->name->toString();
92	
93	            if (str_starts_with($methodName, 'test')) {
94	                return $this->testMethodNameValidator->errors($methodName, $node->getStartLine());
95	            }
96	
97	            if (str_starts_with($methodName, 'provider')) {
98	                return $this->providerNameValidator->errors($methodName, $node->getStartLine());
99	            }
100	        }
101	
102	        return [];
103	    }
104	}
