24	
25	    /** @readonly */
26	    private ClassLikeKindLabel $kindLabel;
27	
28	    /**
29	     * @param list<string> $forbiddenSuffixes class-like name suffixes to forbid
30	     */
31	    public function __construct(array $forbiddenSuffixes = [])
32	    {
33	        $this->forbiddenSuffixes = new ForbiddenClassLikeSuffixes($forbiddenSuffixes);
