68	                    $kind,
69	                    $name,
70	                    $suffix
71	                )
72	            )
73	                ->identifier('customRules.forbiddenClassLikeNameSuffix')
74	                ->line($node->getStartLine())
75	                ->build(),
76	        ];
77	    }
78	}
