39	     */
40	    public function getNodeType(): string
41	    {
42	        return ClassLike::class;
43	    }
44	
45	    /**
46	     * @param ClassLike $node
47	     * @return list<IdentifierRuleError>
48	     */
49	    public function processNode(Node $node, Scope $scope): array
50	    {
51	        if ($node->name === null) {
52	            return [];
53	        }
54	
55	        $name = $node->name->toString();
56	        $suffix = $this->forbiddenSuffixes->matchingSuffix($name);
57	
58	        if ($suffix === null) {
59	            return [];
60	        }
61	
62	        $kind = $this->kindLabel->label($node);
63	
64	        return [
65	            RuleErrorBuilder::message(
66	                sprintf(
67	                    'Rename %s %s to a specific domain name without the "%s" suffix.',
68	                    $kind,
69	                    $name,
70	                    $suffix
71	                )
72	            )
73	                ->identifier('customRules.forbiddenClassLikeNameSuffix')
74	                ->line($node->getStartLine())
75	                ->build(),
76	        ];
77	    }
78	}
