12	final class TestClassScope
13	{
14	    /**
15	     * @var list<string>
16	     * @readonly
17	     */
18	    private array $testNamespacePrefixes;
19	
20	    /**
21	     * @var list<string>
22	     * @readonly
23	     */
24	    private array $restrictedTestNamespacePrefixes;
25	
26	    /**
27	     * @param list<string> $testNamespacePrefixes namespace prefixes that identify test classes
28	     * @param list<string> $restrictedTestNamespacePrefixes namespace prefixes for stricter test rules
29	     */
30	    public function __construct(
31	        array $testNamespacePrefixes = ['Tests'],
32	        array $restrictedTestNamespacePrefixes = ['Tests\\Unit', 'Tests\\Integration', 'Tests\\Property'],
33	    ) {
34	        $this->testNamespacePrefixes = array_map(
35	            static fn (string $prefix): string => rtrim($prefix, '\\') . '\\',
36	            $testNamespacePrefixes,
37	        );
38	        $this->restrictedTestNamespacePrefixes = array_map(
39	            static fn (string $prefix): string => rtrim($prefix, '\\') . '\\',
40	            $restrictedTestNamespacePrefixes,
41	        );
42	    }
43	
44	    /**
45	     * Determines whether the current scope is inside a test class.
46	     */
47	    public function isTestClass(Scope $scope): bool
48	    {
49	        if ($this->isPropertyTestClass($scope)) {
50	            return true;
51	        }
52	
53	        $classReflection = $scope->getClassReflection();
54	        if ($classReflection === null) {
55	            return false;
56	        }
57	
58	        $className = ltrim($classReflection->getName(), '\\');
59	
60	        foreach ($this->testNamespacePrefixes as $prefix) {
61	            if (str_starts_with($className, $prefix)) {
62	                return true;
63	            }
64	        }
65	
66	        return false;
67	    }
68	
69	    /**
70	     * Determines whether the current scope is inside a restricted test class.
71	     */
72	    public function isRestrictedTestClass(Scope $scope): bool
73	    {
74	        if ($this->isPropertyTestClass($scope)) {
75	            return true;
76	        }
77	
78	        if (!$this->isTestClass($scope)) {
79	            return false;
80	        }
81	
82	        $classReflection = $scope->getClassReflection();
83	        if ($classReflection === null) {
84	            return false;
85	        }
86	
87	        $className = ltrim($classReflection->getName(), '\\');
88	
89	        foreach ($this->restrictedTestNamespacePrefixes as $prefix) {
90	            if (str_starts_with($className, $prefix)) {
91	                return true;
92	            }
93	        }
94	
95	        return false;
96	    }
97	
98	    /**
99	     * Identifies named property tests by directory, namespace, or PHPUnit class convention.
100	     */
101	    public function isPropertyTestClass(Scope $scope): bool
102	    {
103	        $class = $scope->getClassReflection();
104	        if ($class === null || $class->isAnonymous()) {
105	            return false;
106	        }
107	
108	        if (str_contains('/' . str_replace('\\', '/', $scope->getFile()), '/tests/Property/')
109	            || str_starts_with($class->getName(), 'Tests\\Property\\')) {
110	            return true;
111	        }
112	
113	        if (!$class->isSubclassOf('PHPUnit\\Framework\\TestCase')) {
114	            return false;
115	        }
116	
117	        return str_ends_with($class->getName(), 'Properties') || $class->hasTraitUse('Eris\\TestTrait');
118	    }
119	}
