16	/**
17	 * Enforces the directory, class, and method conventions for property tests.
18	 *
19	 * @implements Rule<InClassNode>
20	 */
21	final class PropertyTestConventionRule implements Rule
22	{
23	    /**
24	     * Creates the rule with the shared test scope detector.
25	     */
26	    public function __construct(private TestClassScope $testClassScope)
27	    {
28	    }
29	
30	    /**
31	     * @return class-string<InClassNode>
32	     */
33	    public function getNodeType(): string
34	    {
35	        return InClassNode::class;
36	    }
37	
38	    /**
39	     * @param InClassNode $node
40	     * @return list<IdentifierRuleError>
41	     */
42	    public function processNode(Node $node, Scope $scope): array
43	    {
44	        $class = $node->getOriginalNode();
45	        if (!$class instanceof Class_ || !$this->testClassScope->isPropertyTestClass($scope)) {
46	            return [];
47	        }
48	
49	        $className = $node->getClassReflection()->getName();
50	        $name = $class->name !== null ? $class->name->toString() : '';
51	        $errors = [];
52	        if (!str_contains('/' . str_replace('\\', '/', $scope->getFile()), '/tests/Property/')) {
53	            $errors[] = RuleErrorBuilder::message(sprintf('Move property test class %s to tests/Property/%s.php. Property tests must be stored under tests/Property.', $className, $name))
54	                ->identifier('customRules.propertyTestLocation')->line($class->getStartLine())->build();
55	        }
56	        if (preg_match('/^[A-Z][a-zA-Z0-9]*Properties$/D', $name) !== 1) {
57	            $errors[] = RuleErrorBuilder::message(sprintf('Rename property test class %s to <Name>Properties (for example CollectionProperties) and use the same PHP filename.', $className))
58	                ->identifier('customRules.propertyTestClassName')->line($class->getStartLine())->build();
59	        }
60	        if ($class->extends === null || $class->extends->toString() !== 'PHPUnit\\Framework\\TestCase') {
61	            $errors[] = RuleErrorBuilder::message(sprintf('Make property test class %s extend PHPUnit\\Framework\\TestCase directly. Move shared test behavior to collaborators.', $className))
62	                ->identifier('customRules.propertyTestExtends')->line($class->getStartLine())->build();
63	        }
64	        $validator = new PropertyTestMethodValidator();
65	        foreach ($class->getMethods() as $method) {
66	            $errors = array_merge($errors, $validator->errors($method, $className));
67	        }
68	
69	        return $errors;
70	    }
71	}
